const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Hong Kong Polygon (approximate bounding box for simplicity)
  const HK_geometry = ee.Geometry.Polygon(
    [[[113.82, 22.12],
      [113.82, 22.58],
      [114.50, 22.58],
      [114.50, 22.12]]]);

  const date_p1_start = '2020-01-01';
  const date_p1_end = '2020-01-20';
  const date_p2_start = '2020-02-10';
  const date_p2_end = '2020-02-25';

  const collection_name = 'COPERNICUS/S5P/OFFL/L3_NO2';
  const band_name = 'NO2_column_number_density';
  const qa_band = 'qa_value';
  const scale = 1000; // meters

  // Function to process a time period
  const processPeriod = (start_date, end_date, period_name) => {
    let collection = ee.ImageCollection(collection_name)
      .filterBounds(HK_geometry)
      .filterDate(start_date, end_date)
      .select([band_name, qa_band])
      .filter(ee.Filter.gt(qa_band, 0.75)); // Filter for good quality data

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`Error: Empty collection for ${period_name}.`);
      return { mean: null, pixels: 0, images: 0 };
    }

    const meanImage = collection.mean().clip(HK_geometry);

    // Calculate valid pixel count
    const pixelCount = meanImage.select(band_name).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: HK_geometry,
      scale: scale,
      maxPixels: 1e9
    }).get(band_name).getInfo();

    if (pixelCount === 0 || pixelCount === null) {
      console.log(`No valid pixels after masking for ${period_name}.`);
      return { mean: null, pixels: 0, images: collectionSize };
    }

    // Calculate mean NO2
    const meanNO2 = meanImage.select(band_name).reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: HK_geometry,
      scale: scale,
      maxPixels: 1e9
    }).get(band_name).getInfo();

    return { mean: meanNO2, pixels: pixelCount, images: collectionSize };
  };

  // Authenticate and initialize Earth Engine
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });

  // Process Period 1
  const result_p1 = processPeriod(date_p1_start, date_p1_end, 'January 1-20, 2020');
  console.log(`Jan 1-20, 2020 - Images: ${result_p1.images}, Valid Pixels: ${result_p1.pixels}, Mean NO2: ${result_p1.mean !== null ? result_p1.mean.toFixed(8) : 'N/A'}`);

  // Process Period 2
  const result_p2 = processPeriod(date_p2_start, date_p2_end, 'February 10-25, 2020');
  console.log(`Feb 10-25, 2020 - Images: ${result_p2.images}, Valid Pixels: ${result_p2.pixels}, Mean NO2: ${result_p2.mean !== null ? result_p2.mean.toFixed(8) : 'N/A'}`);

  // 5. Validation & Final Answer
  if (result_p1.images === 0 || result_p2.images === 0) {
    console.log("C1"); // Empty Collection
    return;
  }

  if (result_p1.pixels === 0 || result_p2.pixels === 0) {
    console.log("C2"); // No Valid Pixels
    return;
  }

  if (result_p1.mean === null || result_p2.mean === null || isNaN(result_p1.mean) || isNaN(result_p2.mean)) {
    console.log("C3"); // Calculation Failure (null or NaN)
    return;
  }

  if (result_p2.mean < result_p1.mean) {
    console.log("A"); // Yes, NO2 levels decreased
  } else {
    console.log("B"); // No, NO2 levels did not decrease
  }
}

runAnalysis();
